const c=[{id:"P01",title:"Steel · 2007 · Zusammenhänge und Theorie des Aufschiebens",url:"https://studypedia.au.dk/fileadmin/www.studiemetro.au.dk/Procrastination_2.pdf",type:"research",finding:"691 Zusammenhänge aus 216 Arbeiten verbanden Aufschieben mit unangenehmen Aufgaben, geringerer Selbstkontrolle und geringerer Selbstwirksamkeit. Für die Arbeitsabsicht lag r bei -0,03; das Unsicherheitsintervall schloss null ein.",limitation:"Überwiegend Zusammenhangsstudien mit Studierenden. Das zeigt keine Ursachen oder Einzeldiagnosen. Ältere Angaben zur Häufigkeit sind keine aktuellen repräsentativen Werte."},{id:"P02",title:"Sirois & Pychyl · 2013 · Kurzfristige Stimmungsregulation",url:"https://eprints.whiterose.ac.uk/91793/1/Compass%20Paper%20revision%20FINAL.pdf",type:"research",finding:"Ein theoretisches Modell beschreibt, wie Menschen unangenehmen Gefühlen bei der Aufgabe jetzt ausweichen und die Kosten ihrem späteren Selbst überlassen.",limitation:"Theoretische Übersicht ohne neue zusammengefasste Effektgröße. Sie erklärt nicht jede Verzögerung und belegt nicht, dass Gefühle zu benennen Verhalten verändert."},{id:"P03",title:"Gollwitzer & Sheeran · 2006 · Metaanalyse zu Wenn-dann-Plänen",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"In 94 unabhängigen Tests verbesserten konkrete Wenn-dann-Pläne im Durchschnitt das Erreichen von Zielen. Die damalige standardisierte Effektgröße war d = 0,65.",limitation:"Unterschiedliche ältere Studien. Der Effekt bedeutet weder 65 Prozent mehr Erfolg noch einen spezifischen Effekt gegen Aufschieben. ODAs kurze Aufgabenübung wurde nicht geprüft."},{id:"P04",title:"Wang, Wang & Gai · 2021 · Mentales Kontrastieren mit Planung",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8149892/",type:"research",finding:"21 Artikel mit 24 Effekten zeigten einen kleinen bis mittleren durchschnittlichen Nutzen für das Erreichen von Zielen durch mentales Kontrastieren mit Wenn-dann-Plänen.",limitation:"Unterschiedliche Ergebnisse und Hinweise auf Publikationsverzerrung begrenzen die Aussage zur Größe. ODAs kurze Anpassung ist ungeprüft. Nicht machbare Ziele müssen vielleicht losgelassen werden."},{id:"P05",title:"Rozental et al. · 2018 · Kontrollierte Maßnahmen gegen Aufschieben",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2018.01588/full",type:"research",finding:"Zwölf Studien mit 718 Menschen fanden gegenüber inaktiven Kontrollgruppen eine bescheidene durchschnittliche Verringerung des selbstberichteten Aufschiebens.",limitation:"Hauptsächlich Studierende, unterschiedliche Methoden, Qualitätsbedenken und wenige Studien pro Behandlung. Die vorläufigen Befunde belegen weder ODAs Wirkung noch eine allgemeine Rangfolge von Behandlungen."},{id:"P07",title:"Wohl, Pychyl & Bennett · 2010 · Selbstvergebung und Aufschieben",url:"https://www.researchgate.net/publication/222302476_I_forgive_myself_now_I_can_study_How_self-forgiveness_for_procrastinating_can_reduce_future_procrastination",type:"research",finding:"119 Studierende im ersten Jahr wurden vor zwei Zwischenprüfungen befragt. Mehr Selbstvergebung hing mit weniger Aufschieben vor der späteren Prüfung zusammen.",limitation:"Eine beobachtete Gruppe aus einem Kurs. Weder ein ursächlicher Effekt bestimmter Sätze noch ausgeführte Wiedergutmachung wurde belegt. Anfängliche Teilnahmezahlen und Ausfälle sind nicht bestätigt."},{id:"P08",title:"Han & Kim · 2023 · Übersicht zu Maßnahmen für Selbstmitgefühl",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"In 56 randomisierten Studien zeigten Maßnahmen für Selbstmitgefühl begrenzte Hinweise auf kleine bis mittlere unmittelbare Vorteile bei psychischer Belastung.",limitation:"Insgesamt hohes Verzerrungsrisiko, unterschiedliche Programme und wenige aktive Vergleiche. Hier gibt es keinen Beleg, dass ein einzelner Satz Angst behandelt oder Aufschieben verringert."},{id:"P09",title:"Zhou et al. · 2026 · Planung und Bereitschaft anzufangen",url:"https://pubmed.ncbi.nlm.nih.gov/41601124/",type:"research",finding:"Eine randomisierte Studie mit 81 Studierenden berichtete nach MCII weniger Abneigung gegen die Aufgabe und mehr Handlungsbereitschaft als nach positivem Denken.",limitation:"Eine private chinesische Universität und kurze Nachbeobachtung. Der Abstract bestätigt weder tatsächliche Abschlüsse noch tägliche Anfangsquoten, Ausfälle oder den Status einer Vorregistrierung."},{id:"P10",title:"Oettingen et al. · 2015 · Ein Planungsverfahren für Zeitmanagement",url:"https://www.socmot.uni-konstanz.de/sites/default/files/Oettingen_et_al-2015-European_Journal_of_Social_Psychology_0.pdf",type:"research",finding:"Eine akademische MCII-Übung verband Ergebnis, Hindernis, Handlung, Zeit und Ort, gedankliches Proben und einen Wochenkalender. Gemessen wurden geplante Tätigkeitsstunden.",limitation:"Studie 1 teilte 84 deutsche Studierende zufällig Gruppen zu. Planung war das Ergebnis, keine abgeschlossene Arbeit. ODAs Anpassung für alltägliche Aufgaben verändert den Ablauf."},{id:"P11",title:"Biwer et al. · 2023 · Feste und selbst gewählte Pausen",url:"https://pubmed.ncbi.nlm.nih.gov/36859717/",type:"research",finding:"Bei 87 Studierenden wurden selbst gewählte Pausen mit 24/6- und 12/3-Zeitplänen verglichen. Feste Zeitpläne hatten subjektive Vorteile. Ein signifikanter Unterschied beim Abschließen von Aufgaben wurde nicht berichtet.",limitation:"Kleine Stichprobe an einem Tag mit selbstständigem Lernen; nur der Abstract war zugänglich. Fehlende Signifikanz beweist weder gleiche Ergebnisse noch dauerhaft weniger Aufschieben oder einen optimalen 25/5-Rhythmus."},{id:"P12",title:"Albulescu et al. · 2022 · Übersicht über Kurzpausen",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0272460",type:"research",finding:"In 22 Stichproben zeigten kurze Pausen im Durchschnitt deutlichere Vorteile bei Müdigkeit und Energie als bei der Gesamtleistung.",limitation:"Aufgaben und Pausenaktivitäten unterschieden sich. Ein optimaler 25/5-Rhythmus oder verlässliche Leistungssteigerung bei anspruchsvollen Aufgaben wurde nicht belegt."},{id:"P13",title:"Harkin et al. · 2016 · Metaanalyse zum Beobachten von Fortschritten",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Maßnahmen zum Beobachten von Fortschritten verbesserten im Durchschnitt das Erreichen von Zielen in 138 randomisierten Studien.",limitation:"Ziele und Methoden unterschieden sich. Zusätzliche Analysen zu Festhalten und Berichten belegen nicht, dass jede Form die Wirkung verursacht. Öffentliches Teilen und ein zweiminütiger Wochenrhythmus sind nicht nötig."},{id:"P15",title:"Psychological Science · 2026 · Rücknahme der Arbeit zu Fristen",url:"https://journals.sagepub.com/doi/full/10.1177/09567976261488042",type:"guidance",finding:"Die Mitteilung vom 2. September zieht Ariely und Wertenbrochs Arbeit von 2002 zu Fristen zurück. Anlass waren Zweifel an Zuverlässigkeit und Echtheit der Daten.",limitation:"Zurückgezogene Ergebnisse können keine Technik stützen. Die Mitteilung zeigt nicht, dass jeder persönliche Kontrolltermin oder jede Frist wirkungslos ist."},{id:"procrastination-pomodoro",title:"Cirillo · Ursprung der Pomodoro-Technik",url:"https://www.pomodorotechnique.com/francesco-cirillo/",type:"technique",finding:"Der Entwickler beschreibt eine Timer-Routine, die meist mit 25-minütigen Arbeitsblöcken und kurzen Pausen vermittelt wird.",limitation:"Das beschreibt den Ursprung eines Praxistipps, keine unabhängige Wirksamkeitsprüfung. Die genauen Zeiten und ODAs Routine werden durch diese Darstellung des Entwicklers nicht bestätigt."},{id:"if-then-plans",title:"Gollwitzer & Sheeran · 2006 · Metaanalyse zu Wenn-dann-Plänen",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"In 94 unabhängigen Tests verbesserten konkrete Wenn-dann-Pläne im Durchschnitt das Erreichen von Zielen. Die damalige standardisierte Effektgröße war d = 0,65.",limitation:"Unterschiedliche ältere Studien. Der Effekt bedeutet weder 65 Prozent mehr Erfolg noch einen spezifischen Effekt gegen Aufschieben. ODAs kurze Aufgabenübung wurde nicht geprüft."},{id:"self-forgiveness",title:"Wohl, Pychyl & Bennett · 2010 · Selbstvergebung und Aufschieben",url:"https://www.researchgate.net/publication/222302476_I_forgive_myself_now_I_can_study_How_self-forgiveness_for_procrastinating_can_reduce_future_procrastination",type:"research",finding:"119 Studierende im ersten Jahr wurden vor zwei Zwischenprüfungen befragt. Mehr Selbstvergebung hing mit weniger Aufschieben vor der späteren Prüfung zusammen.",limitation:"Eine beobachtete Gruppe aus einem Kurs. Weder ein ursächlicher Effekt bestimmter Sätze noch ausgeführte Wiedergutmachung wurde belegt. Anfängliche Teilnahmezahlen und Ausfälle sind nicht bestätigt."},{id:"procrastination-pomodoro-breaks",title:"Biwer et al. · 2023 · Feste und selbst gewählte Pausen",url:"https://pubmed.ncbi.nlm.nih.gov/36859717/",type:"research",finding:"Bei 87 Studierenden wurden selbst gewählte Pausen mit 24/6- und 12/3-Zeitplänen verglichen. Feste Zeitpläne hatten subjektive Vorteile. Ein signifikanter Unterschied beim Abschließen von Aufgaben wurde nicht berichtet.",limitation:"Kleine Stichprobe an einem Tag mit selbstständigem Lernen; nur der Abstract war zugänglich. Fehlende Signifikanz beweist weder gleiche Ergebnisse noch dauerhaft weniger Aufschieben oder einen optimalen 25/5-Rhythmus."},{id:"P18",title:"Breines & Chen · 2012 · Verständnisvolles Schreiben und Motivation zur Wiedergutmachung",url:"https://self-compassion.org/wp-content/uploads/publications/selfimp.motivation.pdf",type:"research",finding:"In Experiment 2 steigerte verständnisvolles Schreiben bei Studierenden die berichtete Motivation, etwas wiedergutzumachen und eine Wiederholung zu vermeiden.",limitation:"100 aufgenommen, 91 ausgewertet. Ausgeführte Wiedergutmachung, dauerhafte Veränderung und weniger Aufschieben wurden nicht gemessen. ODA ergänzt einen getrennten konkreten Wiedergutmachungsschritt."}],h=[{schemaVersion:2,revision:2,id:"procrastination-1",courseId:"procrastination",locale:"de",title:"Die Aufgabe wartet. Was kostet dich das Aufschieben?",goal:"Prüfe, ob Warten nötig ist. Mach dann einen hilfreichen kleinen Schritt bei deiner aufgeschobenen Aufgabe.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Die Reisekostenabrechnung liegt immer noch da. Was kostet es dich, sie wieder aufzuschieben?",reason:{id:"procrastination-1-delay-cost-reason",label:"Was kostete das letzte Aufschieben, und war Warten nötig?",kind:"text",maxLength:160,optional:!0,suggestions:["Benötigte Informationen waren noch nicht verfügbar","Eintrag vermieden; die Arbeit häufte sich","Erholung oder dringende Versorgung hatten Vorrang"]},why:{id:"procrastination-1-why",label:"Wozu dient diese Aufgabe, oder was kostet das Aufschieben?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aufschieben bedeutet: Du verzögerst etwas, das du tun wolltest, obwohl du erwartest, dass Warten es schwieriger macht. Erholung, eine wichtigere Pflicht oder fehlende Mittel können Warten dagegen rechtfertigen. Prüfe deine tatsächliche Situation, bevor du dich faul nennst.","Eine Erklärung lautet: Wenn du einer unangenehmen Aufgabe ausweichst, tauschst du Erleichterung jetzt gegen Nachteile später. Das ist ein Modell. Es erklärt nicht jede Verzögerung. Benenne das Gefühl oder die praktische Hürde. Ist ein sicherer, hilfreicher Schritt möglich, mach einen kleinen Teil, auch wenn das Unbehagen bleibt. Erleichterung ist keine Voraussetzung. Der konkrete Schritt zählt."],example:{title:"Sarah trägt einen Beleg ein",text:"Um 15 Uhr schiebt Sarah ihre Reisekostenabrechnung vor sich her, weil zwei Belege fehlen. Sie prüft die Regel für fehlende Belege und trägt einen vorhandenen ein. Ihr ist das immer noch peinlich. Sie hält den Eintrag und die offene Frage fest. Die Abrechnung ist nicht fertig. Aber nicht mehr jeder Teil davon liegt still."}},move:{invitation:"Wähle einen Eintrag, Satz oder eine Nachfrage, die zu deiner aufgeschobenen Aufgabe passt.",instructions:["Prüfe zuerst, ob Warten ein tatsächliches Bedürfnis schützt.","Wähle ein Beispiel nur, wenn es zu deiner Aufgabe passt."],prompts:[{id:"procrastination-1-0",label:"Welcher Teil ist unangenehm, und welcher tatsächlich nicht machbar?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Einen Beleg in meine Abrechnung eintragen","Einen hilfreichen Satz für meine Aufgabe schreiben","Eine Regel erfragen, die meine Aufgabe blockiert"],minimum:["Einen vorhandenen Beleg eintragen","Einen brauchbaren Satz schreiben","Eine konkrete Frage zur Regel abschicken"],cue:["Nach meiner nächsten Pause bei der Arbeit","Nachdem ich den Teller vom Abendessen abräume","Wenn eine unklare Regel mich am Weiterarbeiten hindert"],place:["An meinem Arbeitsschreibtisch","Am Tisch in der Küche","Im passenden Nachrichtenverlauf mit einem sicheren Kontakt"],minutes:[2,5,1],fallback:["Zuerst einen bereits vorhandenen Beleg nutzen","Einen Satz entwerfen; die unklare Stelle markieren","Bei Bedarf eine andere erreichbare Ansprechperson fragen"],observation:["Der Beleg, den ich tatsächlich eingetragen habe","Mein geschriebener Satz und was noch unklar bleibt","Meine abgeschickte Regelfrage und eine mögliche Antwort"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Einen Beleg in meine Abrechnung eintragen",minimum:"Einen vorhandenen Beleg eintragen",cue:"Nach meiner nächsten Pause bei der Arbeit",place:"An meinem Arbeitsschreibtisch",fallback:"Zuerst einen bereits vorhandenen Beleg nutzen",observation:"Der Beleg, den ich tatsächlich eingetragen habe",minutes:2},{action:"Einen hilfreichen Satz für meine Aufgabe schreiben",minimum:"Einen brauchbaren Satz schreiben",cue:"Nachdem ich den Teller vom Abendessen abräume",place:"Am Tisch in der Küche",fallback:"Einen Satz entwerfen; die unklare Stelle markieren",observation:"Mein geschriebener Satz und was noch unklar bleibt",minutes:2},{action:"Eine Regel erfragen, die meine Aufgabe blockiert",minimum:"Eine konkrete Frage zur Regel abschicken",cue:"Wenn eine unklare Regel mich am Weiterarbeiten hindert",place:"Im passenden Nachrichtenverlauf mit einem sicheren Kontakt",fallback:"Bei Bedarf eine andere erreichbare Ansprechperson fragen",observation:"Meine abgeschickte Regelfrage und eine mögliche Antwort",minutes:2,kind:"support"}]},suggested:{action:"Einen Beleg in meine Abrechnung eintragen",minimum:"Einen vorhandenen Beleg eintragen",minutes:2,cueHint:"Nach meiner nächsten Pause bei der Arbeit",placeHint:"An meinem Arbeitsschreibtisch",obstacleHint:"Informationen fehlen oder ich möchte der Aufgabe ausweichen",fallbackHint:"Zuerst einen bereits vorhandenen Beleg nutzen",observationHint:"Der Beleg, den ich tatsächlich eingetragen habe",requiresChoice:!0},stopRule:"Verschiebe für diesen Versuch keine dringenden Pflichten zu Gesundheit, Sicherheit oder Verträgen.",accessibleAlternative:"Nutze Hilfsmittel, frage nach Informationen oder wähle Unterstützung, wenn du bei der Aufgabe nicht weiterkommst."},result:{question:"Hast du deinen gewählten hilfreichen Schritt gemacht?",observationPrompt:"Was hast du gemacht, und was bleibt blockiert?"},judgment:{primary:{id:"procrastination-1-decision",scenario:"Sarah hat zwei freie Minuten und die Abrechnungsvorlage. Zwei Belege fehlen. Die Regeln erlauben aber, vorhandene Belege einzutragen.",question:"Welcher Schritt geht das Aufschieben an?",options:[{id:"procrastination-1-sort",text:"Alle Belege zuerst nach Datum sortieren, damit die spätere Arbeit an der Abrechnung leichter wird.",feedback:"Sortieren könnte später helfen. Hier sind vorhandene Einträge bereits möglich. Trage jetzt einen ein und kläre die Regel für fehlende Belege. Warte damit nicht, bis alles vollständig geordnet ist."},{id:"procrastination-1-enter",text:"Die Regel für fehlende Belege prüfen und einen vorhandenen eintragen, auch wenn es ihr weiter peinlich ist.",feedback:"Das klärt die Unsicherheit und schafft in der verfügbaren Zeit ein Ergebnis. Dass Sarah sich weiter schämt, macht den Eintrag nicht ungeschehen. Halte fest, was sich geändert hat und welche Informationen noch fehlen."},{id:"procrastination-1-wait",text:"Für morgen einen längeren Termin wählen, damit sie die gesamte Abrechnung in einem Durchgang fertig machen kann.",feedback:"Zum Abschließen könnte mehr Zeit nötig sein. Das nutzt aber die heutige Startgelegenheit nicht. Verwende die jetzige Zeit für einen Eintrag. Plane danach eine passende Zeit für die restliche Arbeit."}],bestOptionId:"procrastination-1-enter"}},carry:{takeaway:"Benenne die Hürde, prüfe den Bedarf und mach einen hilfreichen Schritt.",followUp:{questionId:"procrastination-1-return",question:"Hielt dich Unbehagen auf, oder fehlte dir weiterhin etwas zum Weiterarbeiten?",observationPrompt:"Was hast du gemacht, und was bleibt blockiert?",adjustmentPrompt:"Welche einzelne Änderung würde deinen nächsten Versuch besser machbar machen?"}},goDeeper:{sections:[{heading:"Eine Verzögerung ist kein Urteil über deinen Charakter",paragraphs:["Steels Übersicht von 2007 sammelte 691 Zusammenhänge aus 216 Arbeiten. Unangenehme Aufgaben, geringere Selbstkontrolle und geringeres Zutrauen in das eigene Können hingen mit Aufschieben zusammen. Solche Zusammenhänge zeigen nicht, was deine Verzögerung verursacht. Ein großer Teil der Forschung betraf Studierende. Die älteren Angaben zur Häufigkeit sind keine aktuellen repräsentativen Werte. [P01]","Der Zusammenhang mit der Absicht zu arbeiten lag bei minus 0,03. Das Unsicherheitsintervall schloss null ein. Dieser durchschnittliche Zusammenhang nahe null sagt nicht, dass alle genug Lust, Zeit, Unterstützung oder Mittel haben. Prüfe deine konkrete Aufgabe: Gibt es einen möglichen Schritt, eine konkurrierende Verantwortung, nötige Anpassungen oder einen Grund aufzuhören? Entscheide nach diesen Fakten, nicht nach einem Etikett für deinen Charakter."]},{heading:"Jetzt Erleichterung, später die Folgen",paragraphs:["Sirois und Pychyl beschreiben ein Modell zur kurzfristigen Stimmungsregulation: Eine unangenehme Aufgabe kann Vermeidung auslösen. Vermeidung kann sofort emotional entlasten. Die unerledigte Arbeit bleibt für später. Ihre Arbeit von 2013 ist eine theoretische Übersicht, keine randomisierte Prüfung dieses Ablaufs oder eine Behandlung. Sie zeigt nicht, dass ein Gefühl zu bemerken besser hilft als praktische Planung. [P02]","Das Gefühl zu benennen und mit einem kleinen Aufgabenteil zu verbinden ist eine Anpassung von ODA. Du musst kein Geständnis schreiben oder dich danach ruhiger fühlen. Wähle eine gewöhnliche, sichere Aufgabe. Fehlen Informationen, kann eine konkrete Nachfrage der hilfreiche Schritt sein. Haben Erholung, Schutz oder eine dringende Pflicht Vorrang, halte diese Wahl ehrlich fest. Spätere Lektionen verbessern denselben Aufgabenplan anhand deiner tatsächlichen Versuche. Du brauchst nicht täglich ein neues Versäumnis zu suchen."]}],sourceIds:["P01","P02"]}},{schemaVersion:2,revision:2,id:"procrastination-2",courseId:"procrastination",locale:"de",title:"Wieder nur vorbereitet? Mach einen brauchbaren Teil fertig",goal:"Schaffe bei derselben Aufgabe einen brauchbaren kleinen Teil. Höre an einem Punkt auf, der zu deiner Zeit passt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Wieder eine Runde Vorbereitung? Sorge diesmal dafür, dass ein brauchbarer Teil der Aufgabe entsteht.",reason:{id:"procrastination-2-preparation-output-reason",label:"Was entstand beim letzten Vorbereiten, und welcher brauchbare Teil fehlt noch?",kind:"text",maxLength:160,optional:!0,suggestions:["Material bereit, noch keinen Satz geschrieben","Eine tatsächlich benötigte Anleitung fehlt","Ein Eintrag gemacht; der nächste fehlt noch"]},why:{id:"procrastination-2-why",label:"Was könntest du tun, sobald ein brauchbarer Teil fertig ist?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bleib bei deiner gewählten Aufgabe. Benenne den Schritt mit einem Verb und einem Ergebnis: einen Beleg eintragen, einen Satz übersetzen oder eine nötige Frage beantworten. Eine Datei zu öffnen bereitet Arbeit vor. Ein brauchbares Ergebnis gehört zur eigentlichen Arbeit. Vorbereitung kann nötig sein. Nenne sie ehrlich so, wenn du das tust.","Ein konkreter Plan verbindet einen verfügbaren Anfang mit einer gewählten Handlung. Forschung stützt diese allgemeine Vorgehensweise, keine magische Zwei-Minuten-Dosis. Wähle einen Umfang, der in deine Zeit passt. Du darfst danach aufhören. Anfangen kann weiterhin unangenehm bleiben. Halte das Ergebnis fest. Bessere Stimmung brauchst du dafür nicht."],example:{title:"Sarahs nächster Eintrag",text:"Nach der Kaffeepause am Dienstag hat Sarah fünf Minuten für dieselbe Abrechnung. Sie überlegt, ihre Belegordner umzugestalten. Stattdessen trägt sie einen weiteren Beleg ein. Die Kategorie ist unklar. Sie markiert sie für eine Nachfrage und hört an ihrer gewählten Zeitgrenze auf. Jetzt gibt es zwei Einträge. Die Abrechnung braucht noch Arbeit."}},move:{invitation:"Behalte deine gespeicherte Aufgabe und deinen kleinen Schritt. Schaffe in deiner verfügbaren Zeit etwas Brauchbares.",instructions:["Behalte die Handlung. Ändere das Minimum nur, wenn du einen anderen Aufgabenteil wählst.","Passe den Ausweichschritt und die Ergebnisnotiz an diesen Aufgabenteil an."],prompts:[],suggestions:{action:["Einen Beleg in meine Abrechnung eintragen","Einen Satz meines Dokuments übersetzen","Eine nötige Frage zu meiner Aufgabe beantworten"],minimum:["Einen vorhandenen Beleg eintragen","Einen Satz als ersten Entwurf übersetzen","Eine brauchbare Antwort schreiben"],cue:["Nach meiner nächsten Pause bei der Arbeit","In meiner nächsten reservierten Zeit für die Aufgabe","Nachdem ich den Teller vom Abendessen abräume"],place:["An meinem Arbeitsschreibtisch","An meinem gut zugänglichen Arbeitsplatz","Am Tisch in der Küche"],minutes:[2,5,10],fallback:["Ordner unverändert lassen; den nächsten Beleg eintragen","Unklaren Begriff markieren; den Satz fertig übersetzen","Bekannten Teil schreiben; nach dem Fehlenden fragen"],observation:["Mein Eintrag und eine mögliche unklare Kategorie","Mein übersetzter Satz und der noch unklare Begriff","Meine geschriebene Antwort und das noch fehlende Detail"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Einen Beleg in meine Abrechnung eintragen",minimum:"Einen vorhandenen Beleg eintragen",cue:"Nach meiner nächsten Pause bei der Arbeit",place:"An meinem Arbeitsschreibtisch",fallback:"Ordner unverändert lassen; den nächsten Beleg eintragen",observation:"Mein Eintrag und eine mögliche unklare Kategorie",minutes:2},{action:"Einen Satz meines Dokuments übersetzen",minimum:"Einen Satz als ersten Entwurf übersetzen",cue:"In meiner nächsten reservierten Zeit für die Aufgabe",place:"An meinem gut zugänglichen Arbeitsplatz",fallback:"Unklaren Begriff markieren; den Satz fertig übersetzen",observation:"Mein übersetzter Satz und der noch unklare Begriff",minutes:2},{action:"Eine nötige Frage zu meiner Aufgabe beantworten",minimum:"Eine brauchbare Antwort schreiben",cue:"Nachdem ich den Teller vom Abendessen abräume",place:"Am Tisch in der Küche",fallback:"Bekannten Teil schreiben; nach dem Fehlenden fragen",observation:"Meine geschriebene Antwort und das noch fehlende Detail",minutes:2}]},suggested:{action:"Einen Beleg in meine Abrechnung eintragen",minimum:"Einen vorhandenen Beleg eintragen",minutes:2,cueHint:"Nach meiner nächsten Pause bei der Arbeit",placeHint:"An meinem Arbeitsschreibtisch",obstacleHint:"Ich verbessere die Vorbereitung, statt etwas zu machen",fallbackHint:"Ordner unverändert lassen; den nächsten Beleg eintragen",observationHint:"Mein Eintrag und eine mögliche unklare Kategorie"},stopRule:"Hör bei dringenden Pflichten oder einer unsicheren Aufgabe auf. Bleibe für nötige Kontakte erreichbar.",accessibleAlternative:"Diktiere, schreibe oder nutze Hilfsmittel. Bitte gezielt um das, was dir zum Weiterarbeiten fehlt."},result:{question:"Hast du deinen gewählten brauchbaren Teil geschaffen?",observationPrompt:"Was ist jetzt entstanden, und was war Vorbereitung?"},judgment:{primary:{id:"procrastination-2-decision",scenario:"Jonas hat vor einem Termin zwei Minuten. Die Vertragsdatei liegt bereit. Er weiß, welcher Satz den ersten Abschnitt beginnt.",question:"Welcher Anfang nutzt die verfügbare Zeit?",options:[{id:"procrastination-2-timer",text:"Zwei Timer-Einstellungen vergleichen und eine wählen, die ihm bei der ganzen Übersetzung helfen könnte.",feedback:"Ein Timer kann eine spätere Einheit strukturieren. Einstellungen zu vergleichen übersetzt hier aber nichts. Datei und Satz sind bereit. Nutze die Zeit für einen ersten Entwurf der Satzübersetzung."},{id:"procrastination-2-outline",text:"Den vollständigen Übersetzungsablauf planen, damit der übrige Vertrag bei der späteren Arbeit übersichtlicher wirkt.",feedback:"Ein Ablaufplan kann helfen, wenn der Weg unklar ist. Jonas kennt den nächsten Satz schon. Den ganzen Ablauf zu planen würde ein mögliches Ergebnis durch noch mehr Vorbereitung ersetzen."},{id:"procrastination-2-unit",text:"Den ersten Satz übersetzen, einen unklaren Begriff markieren und rechtzeitig für seinen Termin aufhören.",feedback:"Das schafft einen brauchbaren Entwurf und benennt die Unsicherheit. Der Vertrag ist damit nicht fertig. Jonas kann rechtzeitig aufhören und den markierten Begriff bei der nächsten Arbeitsgelegenheit wieder aufgreifen."}],bestOptionId:"procrastination-2-unit"}},carry:{takeaway:"Ein kleiner Anfang bringt die Aufgabe voran, wenn dabei brauchbare Arbeit entsteht.",followUp:{questionId:"procrastination-2-return",question:"Entstand durch dein Minimum brauchbare Arbeit, oder trat Vorbereitung an ihre Stelle?",observationPrompt:"Was ist jetzt entstanden, und was war Vorbereitung?",adjustmentPrompt:"Welche einzelne Änderung würde deinen nächsten Versuch besser machbar machen?"}},goDeeper:{sections:[{heading:"Ein Startsignal hilft. Zwei Minuten sind eine Wahl",paragraphs:["Gollwitzer und Sheerans Metaanalyse von 2006 verband 94 unabhängige Tests von Wenn-dann-Plänen. Diese Pläne nennen eine erkennbare Situation und einen vorher gewählten Schritt. In unterschiedlichen Situationen verbesserten sie im Durchschnitt das Erreichen von Zielen. Die damalige standardisierte Effektgröße von 0,65 bedeutet nicht 65 Prozent mehr Erfolg. Sie sagt dein Ergebnis nicht vorher. [P03]","Diese Lektion übernimmt die Verbindung zwischen Startsignal und Handlung für eine alltägliche Aufgabe. Kurze Dauer und ein kleiner Aufgabenteil als Minimum sind Gestaltungsentscheidungen, keine optimierte Forschungsdosis. Der Teil muss der Aufgabe trotzdem dienen. Eine Anleitung zu lesen kann Vorbereitung sein, wenn Schreiben das Ziel ist. Ein entworfener Satz ist Schreiben. Beides kann passen. Behalte die Bezeichnungen getrennt. Höre nach der tatsächlich verfügbaren Zeit auf. Ob du später mehr machst, kannst du anhand von Ergebnis, Zugang und Pflichten entscheiden. Der Anfang muss sich nicht leicht angefühlt haben."]},{heading:"Zeitblöcke sind freiwillig",paragraphs:["Biwer und Kollegen verglichen selbst gewählte Pausen mit 24 Minuten Lernen und sechs Minuten Pause sowie zwölf Minuten Lernen und drei Minuten Pause. Die 87 Studierenden lernten an einem Tag selbstständig. Feste Zeitpläne hatten subjektive Vorteile, etwa weniger Müdigkeit und Ablenkung. Beim Abschließen von Aufgaben wurde kein statistisch signifikanter Unterschied berichtet. Gleiche Ergebnisse sind damit nicht bewiesen. [P11]","Eine breitere Übersicht über Pausen von höchstens zehn Minuten fand deutlichere Vorteile bei Müdigkeit und Energie als bei der Gesamtleistung. Sie belegt keinen optimalen 25/5-Rhythmus. [P12] Wählst du einen Timer, nutze eine Dauer, die zu deiner Situation passt. Vergleiche tatsächliche Arbeit und Müdigkeit. Ein laufender Timer ist noch keine Arbeit. Halte dringende und barrierefreie Kommunikation möglich. Mach nötige Pausen. Du brauchst weder einen besonderen Timer noch einen Kauf oder die gesamte Pomodoro-Routine, um diese Lektion auszuprobieren."]}],sourceIds:["P03","P11","P12"]}},{schemaVersion:2,revision:2,id:"procrastination-3",courseId:"procrastination",locale:"de",title:"Datei offen, Handy in der Hand? Fang dich ab",goal:"Probiere bei deiner bisherigen Aufgabe einen Schritt gegen das Hindernis aus. Notiere, ob du ihn brauchtest.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Du öffnest die Datei und greifst sofort zum Handy? Plane genau für diesen Moment.",reason:{id:"procrastination-3-switch-cost-reason",label:"Was brachte dir das Ausweichen zuletzt, und was kostete es?",kind:"text",maxLength:160,optional:!0,suggestions:["Ein nötiger Kontakt unterbrach meine Arbeit","Kurz erleichtert; der Satz blieb ungeschrieben","Fehlende Information brauchte eine konkrete Nachfrage"]},why:{id:"procrastination-3-why",label:"Was würdest du schützen, wenn du bei dieser Aufgabe bleibst?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Nutze deine letzte Aufgabennotiz. Suche den Moment, in dem Arbeit zu etwas anderem wurde: Nach dem Öffnen der Abrechnung zum Handy greifen oder bei einem unklaren Eintrag aufhören. Ein Schritt für genau diesen Moment lässt sich besser prüfen als „mehr anstrengen“. Verbinde ihn mit demselben kleinen Aufgabenteil wie zuvor.","Forschung zum Verbinden von gewünschtem Ergebnis, Hindernis und Wenn-dann-Plan zeigt bescheidene durchschnittliche Vorteile. Sie verspricht keine Ausführung. Passe den Schritt an die Hürde an. Ablenkung braucht vielleicht eine andere Umgebung. Fehlende Informationen brauchen eine Nachfrage. Betreuung, Krankheit und unsichere Arbeit brauchen Anpassungen oder Unterstützung."],example:{title:"Sarah bemerkt den Griff zum Handy",text:"Beim Abrechnungstermin am Mittwoch öffnet Sarah die Datei und greift zum Handy. Ihr Plan: Handy umdrehen, zuerst einen Beleg eintragen. Das macht sie. Danach beantwortet sie eine nötige Nachricht. Sie hält einen Eintrag fest und dass das Hindernis auftrat. Später in derselben Arbeitszeit lenkt das Handy sie trotzdem wieder ab."}},move:{invitation:"Behalte deine Aufgabe und dein Minimum. Teste deinen Schritt gegen das beobachtete Hindernis.",instructions:["Ändere „Bei einem Hindernis“ passend zu der Hürde, die du tatsächlich gesehen hast.","Noch keine Notiz? Wähle einen Moment, in dem du ausweichst oder Informationen fehlen."],prompts:[],suggestions:{action:["Einen Beleg eintragen, bevor ich Nachrichten lese","Einen Satz schreiben, bevor ich den Tab wechsle","Ein fehlendes Detail durch eine Frage klären"],minimum:["Einen vorhandenen Beleg eintragen","Einen brauchbaren Satz schreiben","Eine konkrete Frage abschicken"],cue:["Wenn ich nach meinem Handy greife","Wenn ich einen anderen Tab öffnen will","Wenn ich bei einem unklaren Eintrag steckenbleibe"],place:["An meinem Arbeitsschreibtisch","An meinem gut zugänglichen Arbeitsplatz","Im passenden Nachrichtenverlauf mit einem sicheren Kontakt"],minutes:[2,5,1],fallback:["Handy umdrehen; für dringende Kontakte erreichbar bleiben","Weitere Tabs geschlossen lassen; den Satz entwerfen","Die Frage über einen anderen verfügbaren Kanal schicken"],observation:["Aufgetretenes Hindernis, mein Umgang damit und fertiger Eintrag","Wechselimpuls, mein Umgang damit und der geschriebene Satz","Das unklare Detail und meine tatsächlich abgeschickte Frage"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Einen Beleg eintragen, bevor ich Nachrichten lese",minimum:"Einen vorhandenen Beleg eintragen",cue:"Wenn ich nach meinem Handy greife",place:"An meinem Arbeitsschreibtisch",fallback:"Handy umdrehen; für dringende Kontakte erreichbar bleiben",observation:"Aufgetretenes Hindernis, mein Umgang damit und fertiger Eintrag",minutes:2},{action:"Einen Satz schreiben, bevor ich den Tab wechsle",minimum:"Einen brauchbaren Satz schreiben",cue:"Wenn ich einen anderen Tab öffnen will",place:"An meinem gut zugänglichen Arbeitsplatz",fallback:"Weitere Tabs geschlossen lassen; den Satz entwerfen",observation:"Wechselimpuls, mein Umgang damit und der geschriebene Satz",minutes:2},{action:"Ein fehlendes Detail durch eine Frage klären",minimum:"Eine konkrete Frage abschicken",cue:"Wenn ich bei einem unklaren Eintrag steckenbleibe",place:"Im passenden Nachrichtenverlauf mit einem sicheren Kontakt",fallback:"Die Frage über einen anderen verfügbaren Kanal schicken",observation:"Das unklare Detail und meine tatsächlich abgeschickte Frage",minutes:2}]},suggested:{action:"Einen Beleg eintragen, bevor ich Nachrichten lese",minimum:"Einen vorhandenen Beleg eintragen",minutes:2,cueHint:"Wenn ich nach meinem Handy greife",placeHint:"An meinem Arbeitsschreibtisch",obstacleHint:"Beim Arbeiten will ich nicht dringende Nachrichten lesen.",fallbackHint:"Handy umdrehen; für dringende Kontakte erreichbar bleiben",observationHint:"Aufgetretenes Hindernis, mein Umgang damit und fertiger Eintrag"},stopRule:"Bleibe für dringende Kontakte und barrierefreie Kommunikation erreichbar. Wähle Unterstützung bei unsicheren oder unzugänglichen Bedingungen.",accessibleAlternative:"Nutze eine barrierefreie Erinnerung, bitte um benötigte Mittel oder probe den Schritt. Kennzeichne das als Vorbereitung."},result:{question:"Hast du deinen geplanten Schritt genutzt und dein Minimum gemacht?",observationPrompt:"Trat das Hindernis auf, und was hast du tatsächlich gemacht?"},judgment:{primary:{id:"procrastination-3-decision",scenario:"Hannah greift nach dem Öffnen ihrer Abschlussarbeit zum Handy. Der erste Fachartikel liegt bereit. Ihr Minimum ist ein Satzentwurf. Dringender Kontakt wird nicht erwartet.",question:"Welcher Schritt passt zu diesem Hindernis?",options:[{id:"procrastination-3-response",text:"Das Handy weglegen, einen Satzentwurf zum Artikel schreiben und danach nach nötigen Nachrichten schauen.",feedback:"Das geht den beobachteten Moment mit dem bisherigen Minimum an. Nötiger Kontakt bleibt danach möglich. Halte fest, ob Hannah das Startsignal rechtzeitig bemerkte und welchen Satz sie tatsächlich schrieb."},{id:"procrastination-3-later",text:"Eine längere Einheit am Wochenende planen, damit die heutige Ablenkung für das Kapitel weniger ins Gewicht fällt.",feedback:"Mehr Wochenendzeit könnte insgesamt helfen. Das aktuelle Startsignal zum Wechseln bleibt aber unverändert. Teste einen machbaren Schritt in diesem Moment, bevor du eine größere Einheit hinzufügst."},{id:"procrastination-3-inspire",text:"Das Ziel der Abschlussarbeit noch einmal lesen und sich das fertige Kapitel vorstellen, bevor sie entscheidet, was sie schreibt.",feedback:"Das Ziel zu erinnern kann Orientierung geben. Hannah braucht auch einen Schritt beim Griff zum Handy und einen tatsächlichen Satz. Nachdenken allein würde diesen Schritt heute nicht prüfen."}],bestOptionId:"procrastination-3-response"}},carry:{takeaway:"Wähle fürs beobachtete Hindernis einen machbaren Schritt. Prüfe danach, ob etwas Brauchbares entstanden ist.",followUp:{questionId:"procrastination-3-return",question:"Hast du das Hindernis rechtzeitig bemerkt, und war dein geplanter Schritt möglich?",observationPrompt:"Trat das Hindernis auf, und was hast du tatsächlich gemacht?",adjustmentPrompt:"Welche einzelne Änderung würde deinen nächsten Versuch besser machbar machen?"}},goDeeper:{sections:[{heading:"Was ein Plan fürs Hindernis hinzufügt",paragraphs:["Mentales Kontrastieren mit Wenn-dann-Plänen verbindet ein gewünschtes Ergebnis mit einem Hindernis und einem geplanten Schritt. Wang und Kollegen bündelten 21 Artikel mit 24 unabhängigen Effekten. Im Durchschnitt zeigte sich ein kleiner bis mittlerer Nutzen für das Erreichen von Zielen. Die Ergebnisse unterschieden sich und zeigten Hinweise auf Publikationsverzerrung. Das Vorgehen kann auch helfen, ein unmögliches Ziel loszulassen. Es verlangt nicht, jede Hürde zu überwinden. [P04]","Bei Oettingens Studienübung von 2015 wählten Studierende ein wichtiges Anliegen, stellten sich Ergebnis und Hindernis vor, wählten einen Schritt, ergänzten Zeit und Ort, probten ihn gedanklich und erstellten einen Wochenkalender. Gemessen wurden geplante Tätigkeitsstunden, keine abgeschlossene Arbeit. [P10] Dein kurzer Aufgabenplan verändert diesen Ablauf. Hier geht es um tatsächliche Ergebnisse. Vorstellen, Proben, Planen und Handeln sind keine austauschbaren Arten von Fortschritt. Auch wurde nicht gezeigt, dass ein Plan besser ist als fünf."]},{heading:"Bereitschaft ist noch kein belegter Anfang",paragraphs:["Zhous jüngere randomisierte Studie umfasste 81 Studierende an einer privaten chinesischen Universität. Der zugängliche Abstract berichtet nach der Planungsstrategie weniger Abneigung gegen die Aufgabe und mehr Handlungsbereitschaft als nach positivem Denken. Die Studie maß die Bereitschaft anzufangen, keine belegten Aufgabenanfänge oder Abschlüsse. Setze Bereitschaft nicht mit Ausführung gleich. [P09]","Positive Gedanken sind nicht automatisch nutzlos. Ein Hindernis muss kein innerer Fehler sein. Dieser Versuch beginnt bei dem Moment, in dem du ausgewichen bist oder deiner praktischen Hürde. Ein hilfreicher Schritt ist einer, den du in der tatsächlichen Situation erkennen und machen kannst. Tritt das Hindernis nie auf, bleibt der Schritt ungeprüft. Er ist dann nicht gescheitert. Tritt es auf und der Schritt ist unmöglich, ändere Vorbereitung, Umfang oder Unterstützung. Behalte Aufgabe und Richtung bei. Ändere die Bedingung, die deine Notiz zeigt."]}],sourceIds:["P04","P10","P09"]}},{schemaVersion:2,revision:2,id:"procrastination-4",courseId:"procrastination",locale:"de",title:"Frist verpasst? Bring in Ordnung, was du kannst",goal:"Wähle eine machbare Wiedergutmachung, kehre zur Aufgabe zurück oder hole Unterstützung. Versprich nur, was du liefern kannst.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Die Frist ist vorbei? Eine ehrliche Nachricht sagt der wartenden Person, wie es weitergeht.",reason:{id:"procrastination-4-owed-repair-reason",label:"Was musst du klären, und was würde weiteres Schweigen oder Versprechen kosten?",kind:"text",maxLength:160,optional:!0,suggestions:["Ich schulde jemandem eine aktuelle Mitteilung","Keine Mitteilung nötig; zur Arbeit zurückkehren","Kontakt ist unsicher; Unterstützung holen"]},why:{id:"procrastination-4-why",label:"Welche Verantwortung oder Grenze braucht jetzt deine Aufmerksamkeit?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Halte deine Aufgabennotiz ehrlich. Wartet jemand, prüfe, ob du eine Mitteilung oder Wiedergutmachung schuldest. Benenne, was offen ist und was du liefern kannst. Freundlichkeit verschiebt keine Frist, löscht keine Folgen und rechtfertigt keine Versprechen über deine Möglichkeiten hinaus.","In einem Experiment steigerte verständnisvolles Schreiben die berichtete Motivation, einen Fehler wiedergutzumachen. Ob das tatsächlich geschah, wurde nicht gemessen. Nutze diese Unterscheidung hier: Ein fairer Satz ist Vorbereitung. Eine Mitteilung zu schicken oder einen Aufgabenteil zu machen ist Handlung. Wähle einen Schritt als Minimum. Halte weitere Schritte getrennt fest. Vergebung ist kein vorgeschriebenes Gefühl."],example:{title:"Sarahs ehrliche Mitteilung",text:"Am Donnerstagmorgen ist Sarahs Abrechnung überfällig. Sie schreibt: „Ich habe sie aufgeschoben. Ich kann jetzt meinen Teil in Ordnung bringen.“ Sie schickt der Buchhaltung einen ehrlichen Stand mit ihrer Frage zu fehlenden Belegen und der offenen Arbeit. Eine Antwort gibt es noch nicht. Sie hält die Nachricht fest. Einen Beleg einzutragen bleibt ein eigener nächster Schritt."}},move:{invitation:"Bleib bei deiner Aufgabe. Wähle eine nötige Wiedergutmachung, eine Rückkehr zur Arbeit oder sichere Unterstützung.",instructions:["Prüfe zuerst, was tatsächlich deine Verantwortung ist, bevor du einen Schritt wählst.","Wähle einen Schritt als Minimum. Halte zusätzliche Schritte getrennt fest."],prompts:[],suggestions:{action:["Einen machbaren neuen Stand zur Aufgabe mitteilen","Einen brauchbaren Teil meiner Aufgabe schreiben","Um Hilfe beim Aufteilen meiner aufgeschobenen Aufgabe bitten"],minimum:["Ehrlich Umfang und Zeitplan in einer Nachricht mitteilen","Einen brauchbaren Satz für meine Aufgabe schreiben","Eine Bitte zum Aufteilen der Aufgabe abschicken"],cue:["In meiner nächsten sicheren Pause bei der Arbeit","In meiner nächsten reservierten Zeit für die Aufgabe","Beim nächsten vereinbarten Gespräch für Unterstützung"],place:["Im passenden Nachrichtenverlauf bei der Arbeit","An meinem gut zugänglichen Arbeitsplatz","Im Nachrichtenverlauf mit einer sicheren unterstützenden Person"],minutes:[5,2,10],fallback:["Aktuellen Stand schicken, ohne unsichere Zeiten zu versprechen","Bekannten Teil entwerfen; ein fehlendes Detail markieren","Falls nicht erreichbar, eine andere vertraute Person fragen"],observation:["Meine abgeschickte Mitteilung und eine mögliche Antwort","Der Satz, den ich für die Aufgabe schrieb","Meine Bitte zum Aufteilen und eine mögliche Antwort"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Einen machbaren neuen Stand zur Aufgabe mitteilen",minimum:"Ehrlich Umfang und Zeitplan in einer Nachricht mitteilen",cue:"In meiner nächsten sicheren Pause bei der Arbeit",place:"Im passenden Nachrichtenverlauf bei der Arbeit",fallback:"Aktuellen Stand schicken, ohne unsichere Zeiten zu versprechen",observation:"Meine abgeschickte Mitteilung und eine mögliche Antwort",minutes:5},{action:"Einen brauchbaren Teil meiner Aufgabe schreiben",minimum:"Einen brauchbaren Satz für meine Aufgabe schreiben",cue:"In meiner nächsten reservierten Zeit für die Aufgabe",place:"An meinem gut zugänglichen Arbeitsplatz",fallback:"Bekannten Teil entwerfen; ein fehlendes Detail markieren",observation:"Der Satz, den ich für die Aufgabe schrieb",minutes:2},{action:"Um Hilfe beim Aufteilen meiner aufgeschobenen Aufgabe bitten",minimum:"Eine Bitte zum Aufteilen der Aufgabe abschicken",cue:"Beim nächsten vereinbarten Gespräch für Unterstützung",place:"Im Nachrichtenverlauf mit einer sicheren unterstützenden Person",fallback:"Falls nicht erreichbar, eine andere vertraute Person fragen",observation:"Meine Bitte zum Aufteilen und eine mögliche Antwort",minutes:2,kind:"support"}]},suggested:{action:"Einen machbaren neuen Stand zur Aufgabe mitteilen",minimum:"Ehrlich Umfang und Zeitplan in einer Nachricht mitteilen",minutes:5,cueHint:"In meiner nächsten sicheren Pause bei der Arbeit",placeHint:"Im passenden Nachrichtenverlauf bei der Arbeit",obstacleHint:"Ich möchte schweigen oder mehr versprechen als machbar",fallbackHint:"Aktuellen Stand schicken, ohne unsichere Zeiten zu versprechen",observationHint:"Meine abgeschickte Mitteilung und eine mögliche Antwort",requiresChoice:!0},stopRule:"Wähle ein alltägliches Versäumnis. Gib dir nicht die Schuld für Schaden, den andere dir zufügen. Ist Kontakt unsicher, pausiere und hole Unterstützung.",accessibleAlternative:"Wähle eine sichere Nachricht, unterstützte Kommunikation oder Unterstützung, wenn direkter Kontakt unsicher wäre."},result:{question:"Hast du deine gewählte Wiedergutmachung oder Rückkehr zur Aufgabe ausgeführt?",observationPrompt:"Welcher einzelne Schritt fand statt, und was ist noch offen?"},judgment:{primary:{id:"procrastination-4-capacity-repair-decision",scenario:"Daniel hat den versprochenen Entwurf nicht geliefert. Das Team braucht eine Mitteilung. Einen Abschnitt kann er heute liefern. Für den gesamten Entwurf braucht er mehr Zeit.",question:"Welcher Schritt passt zu seinen jetzigen Möglichkeiten?",options:[{id:"procrastination-4-finish",text:"Zuerst den verfügbaren Abschnitt fertig machen und das Team erst informieren, wenn der Entwurf beruhigend aussieht.",feedback:"Den Abschnitt zu schreiben zählt. Aber das Team wartet schon und braucht aktuelle Informationen. Teile jetzt ehrlich Umfang und Zeitplan mit. Schreibe danach den Abschnitt, der heute möglich ist."},{id:"procrastination-4-revise-first",text:"Jetzt eine neue Frist für den gesamten Entwurf erbitten. Mit dem möglichen Abschnitt warten, bis der Zeitplan vereinbart ist.",feedback:"Neu zu verhandeln kann nötig sein. Das Team kann heute aber aktuelle Informationen und einen brauchbaren Abschnitt erhalten. Schlage einen realistischen restlichen Zeitplan vor und liefere den möglichen Teil, sofern das Team kein Warten braucht."},{id:"procrastination-4-repair",text:"Das verpasste Versprechen anerkennen, machbaren Umfang und Zeitplan vorschlagen und danach den Abschnitt schreiben, den er liefern kann.",feedback:"Das stellt sich den Folgen, ohne ein unmögliches Versprechen hinzuzufügen. Nachricht und Abschnitt sind konkrete Schritte. Ob das Team zustimmt, entscheidet es selbst. Halte seine Antwort deshalb ehrlich fest."}],bestOptionId:"procrastination-4-repair"}},carry:{takeaway:"Ein fairer Satz unterstützt Wiedergutmachung. Sie geschieht durch den Schritt, den du tatsächlich machst.",followUp:{questionId:"procrastination-4-chosen-act-return",question:"Passte deine gewählte Wiedergutmachung, Rückkehr oder Unterstützung zu deinen tatsächlichen Möglichkeiten?",observationPrompt:"Was hast du gemacht, und was braucht noch eine Antwort?",adjustmentPrompt:"Welche einzelne Änderung würde deinen nächsten Versuch besser machbar machen?"}},goDeeper:{sections:[{heading:"Freundlichkeit und Wiedergutmachung sind unterschiedliche Ergebnisse",paragraphs:["In Breines und Chens Experiment von 2012 beschrieben Studierende eine kürzlich begangene Handlung, die sie für falsch hielten. Danach schrieben sie mit Freundlichkeit und Verständnis an sich selbst. Von 100 aufgenommenen Personen wurden 91 ausgewertet. Die verständnisvoll schreibende Gruppe berichtete mehr Motivation zur Wiedergutmachung und gegen Wiederholung als die Vergleichsgruppen. Abgeschlossene Entschuldigungen, Wiedergutmachungen oder langfristig weniger Aufschieben wurden nicht belegt. [P18]","Diese Lektion nutzt einen kürzeren fairen Satz für eine gewöhnliche aufgeschobene Aufgabe. Dazu kommt ein getrennt gewählter konkreter Schritt. Das ist eine Anpassung von ODA, nicht die untersuchte Übung. Du kannst sicher informieren, einen Fehler korrigieren, einen vereinbarten Teil liefern, um Anpassung bitten oder einen ungeeigneten Plan beenden. Die Notiz benennt, was tatsächlich geschah. Deine Verantwortung muss zu deinem tatsächlichen Handeln passen. Du schuldest keinen Kontakt, keine Versöhnung und keine Entschuldigung dafür, dass dir jemand Schaden zugefügt hat."]},{heading:"Was Befunde zur Selbstvergebung nicht versprechen",paragraphs:["Wohl, Pychyl und Bennett untersuchten 119 Studierende im ersten Jahr eines Psychologiekurses. Sie wurden unmittelbar vor jeder von zwei Zwischenprüfungen befragt. Mehr Selbstvergebung hing mit weniger Aufschieben vor der zweiten Prüfung zusammen. Dieser beobachtete Zusammenhang beweist nicht, dass Vergebung die Veränderung verursachte. Er belegt auch keinen bestimmten Satz, der bei der Rückkehr zu einer Aufgabe hilft. [P07]","Selbstvergebung und Selbstmitgefühl sind verwandt, aber verschieden. Han und Kims Übersicht über 56 randomisierte Studien zu Selbstmitgefühl fand begrenzte Hinweise auf Vorteile bei psychischer Belastung. Das allgemeine Verzerrungsrisiko war hoch. Sie bestätigt keinen einzelnen Satz als Behandlung und zeigt nicht, dass dein nächster Aufgabenanfang dadurch leichter wird. [P08] Du darfst dich fair beschreiben, auch wenn Bedauern oder Frust bleiben. Prüfe weiter, ob die nächste Verpflichtung realistisch ist und Wiedergutmachung oder Rückkehr tatsächlich stattfinden. Eine Gefühlsverwandlung brauchst du nicht."]}],sourceIds:["P18","P07","P08"]}},{schemaVersion:2,revision:2,id:"procrastination-5",courseId:"procrastination",locale:"de",title:"Wieder nicht angefangen? Plane nächste Woche einen passenden Zeitpunkt",goal:"Behalte einen hilfreichen Aufgabenplan. Ändere eine beobachtete Hürde und plane den nächsten machbaren Versuch.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Manche Anfänge klappten, andere nicht? Plane die nächste Woche anhand deiner Notizen.",reason:{id:"procrastination-5-reason",label:"Ist diese Aufgabe ihren Aufwand diese Woche noch wert?",kind:"text",maxLength:160,optional:!0,suggestions:["Eine Verpflichtung weiter voranbringen","Einen immer wieder scheiternden Plan ändern","Bei einem wiederkehrenden Problem Hilfe holen"]},why:{id:"procrastination-5-why",label:"Ist diese Aufgabe ihren Aufwand diese Woche noch wert?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Nutze deine gespeicherte Aufgabe, Richtung, dein Minimum und deine Versuche. Fortschritte zu prüfen kann Menschen im Durchschnitt helfen, Ziele zu erreichen. Unterscheide Plan und Versuch sowie Versuch und brauchbare Arbeit. Ohne Eintrag bleibt der Ausgang unbekannt, weder Misserfolg noch Erfolg.","Behalte, was geholfen hat. Ändere eine Bedingung, die dich blockierte. Ein persönlicher Kontrolltermin darf ein Versuch bleiben. Eine geschuldete Frist zu ändern verlangt Kommunikation und Zustimmung. Speichere deinen nächsten hilfreichen Schritt. ODA plant den Rückblick am nächsten Tag. Kennst du noch kein passendes Startsignal, wähle einen ersten machbaren Versuch. Hole parallel Unterstützung, wenn Aufschieben dauerhaft Schaden verursacht."],example:{title:"Sarah plant die nächste Woche",text:"Am Freitag schaut Sarah auf dieselbe Abrechnung: drei eingetragene Belege, eine unbeantwortete Frage und eine geplante Zeit, die sie nicht nutzte. In Arbeitspausen hatte sie Zugang, spätabends nicht. Sie plant den nächsten Eintrag für Montag nach der Pause und prüft, wer noch eine Nachricht braucht. Die Abrechnung bleibt offen. Der nächste Plan nutzt ihre Notizen."}},move:{invitation:"Behalte deine Aufgabe und Startsignale, die passten. Ändere die Bedingung, die dich tatsächlich blockiert hat.",instructions:["Noch kein hilfreiches Startsignal festgehalten? Nenne eine erste machbare Gelegenheit.","Speichere den nächsten Schritt. ODA plant den Rückblick für den folgenden Tag."],prompts:[],suggestions:{action:["Einen Beleg in meine Abrechnung eintragen","Einen brauchbaren Teil meiner Aufgabe schreiben","Um Hilfe bei einer anderen Arbeitszeit bitten"],minimum:["Einen vorhandenen Beleg eintragen","Einen brauchbaren Satz für meine Aufgabe schreiben","Eine Bitte um Unterstützung beim Zeitplan abschicken"],cue:["Nach meiner nächsten verfügbaren Pause bei der Arbeit","In meiner nächsten reservierten Zeit zum Schreiben","Beim nächsten vereinbarten Gespräch über meinen Zeitplan"],place:["An meinem Arbeitsschreibtisch","An meinem gut zugänglichen Arbeitsplatz","Im Nachrichtenverlauf mit einer sicheren unterstützenden Person"],minutes:[2,5,10],fallback:["Stattdessen morgen eine verfügbare Arbeitspause nutzen","Stattdessen die für morgen reservierte Schreibzeit nutzen","Falls nicht erreichbar, eine andere vertraute Ansprechperson fragen"],observation:["Mein fertiger Eintrag und ob der Zugang passte","Mein geschriebener Satz und ob die Zeit passte","Meine Bitte zum Zeitplan und eine mögliche Antwort"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Einen Beleg in meine Abrechnung eintragen",minimum:"Einen vorhandenen Beleg eintragen",cue:"Nach meiner nächsten verfügbaren Pause bei der Arbeit",place:"An meinem Arbeitsschreibtisch",fallback:"Stattdessen morgen eine verfügbare Arbeitspause nutzen",observation:"Mein fertiger Eintrag und ob der Zugang passte",minutes:2},{action:"Einen brauchbaren Teil meiner Aufgabe schreiben",minimum:"Einen brauchbaren Satz für meine Aufgabe schreiben",cue:"In meiner nächsten reservierten Zeit zum Schreiben",place:"An meinem gut zugänglichen Arbeitsplatz",fallback:"Stattdessen die für morgen reservierte Schreibzeit nutzen",observation:"Mein geschriebener Satz und ob die Zeit passte",minutes:2},{action:"Um Hilfe bei einer anderen Arbeitszeit bitten",minimum:"Eine Bitte um Unterstützung beim Zeitplan abschicken",cue:"Beim nächsten vereinbarten Gespräch über meinen Zeitplan",place:"Im Nachrichtenverlauf mit einer sicheren unterstützenden Person",fallback:"Falls nicht erreichbar, eine andere vertraute Ansprechperson fragen",observation:"Meine Bitte zum Zeitplan und eine mögliche Antwort",minutes:2,kind:"support"}]},suggested:{action:"Einen Beleg in meine Abrechnung eintragen",minimum:"Einen vorhandenen Beleg eintragen",minutes:2,cueHint:"Nach meiner nächsten verfügbaren Pause bei der Arbeit",placeHint:"An meinem Arbeitsschreibtisch",obstacleHint:"Meine geplante Arbeitszeit ist vielleicht nicht verfügbar",fallbackHint:"Stattdessen morgen eine verfügbare Arbeitspause nutzen",observationHint:"Mein fertiger Eintrag und ob der Zugang passte"},stopRule:"Hole jetzt Unterstützung, wenn Aufschieben dein Leben beeinträchtigt. Handle bei dringenden Pflichten so, wie es die Situation erfordert.",accessibleAlternative:"Wähle Hilfe bei der Arbeit, eine Bitte um Unterstützung, eine machbare Grenze oder eine Pause."},result:{question:"Hast du deinen nächsten gewählten kleinen Schritt ausgeführt?",observationPrompt:"Welche brauchbare Arbeit oder Bitte um Unterstützung fand tatsächlich statt?"},judgment:{primary:{id:"procrastination-5-decision",scenario:"Nora schrieb am Dienstag Sätze für ihre Bewerbung. Die Zeit am Donnerstag war nicht verfügbar. Das vereinbarte Gegenlesen durch eine Freundin half. Die Bewerbungsfrist bleibt fest.",question:"Was sollte nächste Woche bleiben, und was sich ändern?",options:[{id:"procrastination-5-more",text:"Tägliche persönliche Kontrolltermine hinzufügen, damit jeder geplante Anfang eine nähere Konsequenz und ein klares Ziel hat.",feedback:"Mehr Kontrolltermine könnten Struktur geben. Die Notiz zeigt aber eine nicht verfügbare Zeit am Donnerstag. Behalte das hilfreiche Gegenlesen. Ändere zuerst diese Zeit, bevor du jeden Tag zusätzlichen Druck einplanst."},{id:"procrastination-5-adjust",text:"Das Gegenlesen behalten, das Startsignal am Donnerstag ändern und nächste Woche tatsächliche Anfänge sowie geschriebene Bewerbungssätze vergleichen.",feedback:"Das nutzt die beobachteten passenden Bedingungen und behält die echte Frist im Blick. Die nächste Notiz sollte Versuche und brauchbaren Text zeigen. Sprich mit anderen, wenn sich eine vereinbarte Verpflichtung ändert."},{id:"procrastination-5-remove",text:"Persönliche Kontrolltermine weglassen und nur die letzte Frist nutzen, solange die Forschung zu Fristen unsicher bleibt.",feedback:"Unsichere allgemeine Befunde löschen Noras hilfreiche Erfahrung mit dem Gegenlesen nicht. Behalte es als gewählten Versuch, ohne es als bewiesene Lösung auszugeben. Gehe die zeitliche Hürde direkt an."}],bestOptionId:"procrastination-5-adjust"}},carry:{takeaway:"Behalte die hilfreiche Bedingung, ändere die blockierende und halte ehrlich fest, was entstanden ist.",followUp:{questionId:"procrastination-5-work-or-support-return",question:"Fand dein nächster Arbeits- oder Unterstützungsschritt bei der gewählten Gelegenheit statt?",observationPrompt:"Welche Arbeit oder Unterstützungsbitte fand statt, und passte das Startsignal?",adjustmentPrompt:"Welche einzelne Änderung würde deinen nächsten Versuch besser machbar machen?"}},goDeeper:{sections:[{heading:"Nutze deine Notizen, statt immer neue Werkzeuge zu sammeln",paragraphs:["Harkin und Kollegen bündelten 138 randomisierte Studien zum Beobachten von Fortschritten bei unterschiedlichen Zielen. Solche Maßnahmen verbesserten im Durchschnitt das Erreichen von Zielen. Festhalten und Berichten hingen in zusätzlichen Analysen mit größeren Effekten zusammen. Diese Zusammenhänge beweisen aber nicht, dass jede Art des Teilens Verbesserungen verursacht. Öffentliches Teilen ist nicht nötig. Dieser Plan legt einen ODA-Rückblick am nächsten Tag an. Ein Wochenvergleich bleibt freiwillig in deinem privaten Kalender. Hier wird kein zweiter Termin gespeichert. [P13]","Beantworte mit deinen datierten Versuchen eine konkrete Frage: Ermöglichten Startsignal, Minimum und geplanter Schritt brauchbare Arbeit? Ein fertiger Teil bedeutet keine fertige Aufgabe. Trat ein Hindernis nicht auf, bleibt der geplante Ausweichschritt ungeprüft. Lass Lücken im Verlauf sichtbar. Behalte nächste Woche die passende Bedingung. Ändere die Hürde, die deine Notiz zeigt. Dient die Aufgabe deinen Pflichten oder deiner Richtung nicht mehr, erwäge neu zu verhandeln, zu pausieren oder aufzuhören. Eine weitere Technik ist nicht immer nötig."]},{heading:"Unterstützung und Fristen brauchen ehrliche Grenzen",paragraphs:["Rozentals kontrollierte Übersicht umfasste zwölf Studien mit 718 Menschen, hauptsächlich Studierenden. Psychologische Maßnahmen verringerten selbstberichtetes Aufschieben im Durchschnitt gegenüber inaktiven Kontrollen. Studienqualität, unterschiedliche Methoden und wenige Studien pro Behandlungsart machen die Befunde vorläufig. Sie zeigen weder, dass ODA wirkt, noch dass jedes Format professionelle Anleitung braucht. Hole dir Abklärung oder Unterstützung, wenn die Folgen es nahelegen. Das darf parallel zu diesem Versuch geschehen. [P05]","Die bekannte Arbeit von Ariely und Wertenbroch zu selbst gesetzten Fristen wurde im September 2026 zurückgezogen. Es gab Zweifel an Zuverlässigkeit und Echtheit der Daten. Ihre Ergebnisse können keine Technik stützen. Die Mitteilung zeigt nicht, dass jeder Kontrolltermin scheitert. [P15] Eine persönliche Erinnerung darf ein freiwilliger Versuch bleiben. Fristen von Arbeitgebern, Kunden oder Hochschulen sind tatsächliche Verpflichtungen. Sprich mit den Beteiligten und hole Zustimmung ein, bevor du sie änderst. Ersetze dringendes Handeln für Gesundheit, Sicherheit, Recht oder Verträge nicht durch selbst auferlegten Druck."]}],sourceIds:["P13","P05","P15"]}}],u=[{id:"1552360708-ebcdf76845ac",alt:"Eine Frau sitzt am Fenster und denkt nach"},{id:"1448387473223-5c37445527e7",alt:"Ein Fuß tritt auf die erste Treppenstufe"},{id:"1553044020-8c90843adf96",alt:"Gelbe Haftnotizen und ein Stift"},{id:"1778958619388-b529cc4e78e8",alt:"Eine junge Frau trinkt am Fenster Tee"},{id:"1506784983877-45594efa4cbe",alt:"Eine Kaffeetasse steht auf einem offenen Terminkalender"}],s=[1,2,0,2,1],d={id:"procrastination",title:"Die Aufgabe wartet. Was kostet dich das Aufschieben?",subtitle:"Eine aufgeschobene Aufgabe. Fünf Lektionen, um brauchbare Arbeit zu beginnen, Hindernisse anzugehen und mit einem ehrlichen Plan weiterzumachen.",description:"Mach aus einer aufgeschobenen Aufgabe kein Urteil über dich. Probiere brauchbare Arbeit aus, halte die Hürde fest und kläre oder ändere, was deine Woche braucht.",scope:"Übungen für alltägliches Aufschieben, keine Psychotherapie. Geht das Aufschieben mit starker Angst, länger gedrückter Stimmung oder Aufmerksamkeitsproblemen einher und beeinträchtigt dein Leben deutlich, kannst du fachliche Unterstützung holen.",outcome:"Ein brauchbarer Aufgabenteil, ein Schritt gegen eine Hürde und ein machbarer nächster Termin.",photo:{id:"1758598304525-c2bc7aada66d",alt:"Eine Frau arbeitet am Laptop an einem Schreibtisch zwischen Pflanzen"},lang:"de",lessons:h.map((e,t)=>{const n=e.judgment.primary,r=n.options.find(i=>i.id===n.bestOptionId),a=n.options.filter(i=>i.id!==n.bestOptionId);return a.splice(s[t],0,r),{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,practice:[...e.move.instructions,"Komm hierher zurück und halte fest, was tatsächlich passiert ist."].slice(0,3),reflection:e.direction.reason.label,question:`${n.scenario} ${n.question}`,options:a.map(i=>i.text),correct:s[t],feedback:r.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,deeper:e.goDeeper.sections,example:e.idea.example,photo:u[t]}})},l=Object.freeze(Object.defineProperty({__proto__:null,COURSE:d,LESSONS_V2:h,SOURCES:c},Symbol.toStringTag,{value:"Module"}));export{l as p};
